        // dp[0][a] = a
        // dp[k][a] = (1/(a+1)) * sum_{j=0}^{a} dp[k-1][j]

        // We need dp[k][a] for each prime factor with initial exponent a.

        // Since k can be up to 10^4 and a can be up to ~50, we can compute this.

        // But note: the maximum exponent for any prime factor of n <= 10^15 is at most log2(10^15) ≈ 50.

        // Let's find the maximum exponent among all prime factors.
        int maxExp = 0;
        for (int e : factors.values()) {
            maxExp = Math.max(maxExp, e);
