        // dp[i][j] = (1/(j+1)) * sum_{m=0}^{j} dp[i-1][m]

        // We can optimize the sum using prefix sums.

        long[][] dp = new long[k + 1][maxExp + 1];

        // Base case
        for (int j = 0; j <= maxExp; j++) {
            dp[0][j] = j;
        }

