            long[][] dp2 = new long[k + 1][a + 1];

            // Base case
            for (int j = 0; j <= a; j++) {
                dp2[0][j] = modPow(p, j, MOD);
            }

            for (int i = 1; i <= k; i++) {
                long[] prefix = new long[a + 2];
                prefix[0] = 0;
                for (int j = 0; j <= a; j++) {
                    prefix[j + 1] = (prefix[j] + dp2[i - 1][j]) % MOD;
                }
                for (int j = 0; j <= a; j++) {
                    long sum = prefix[j + 1];
                    dp2[i][j] = (sum * inv[j + 1]) % MOD;
                }
            }

            result = (result * dp2[k][a]) % MOD;
        }

        System.out.println(result);
    }
