                factors.put(i, factors.getOrDefault(i, 0) + 1);
                temp /= i;
            }
        }
        if (temp > 1) {
            factors.put(temp, factors.getOrDefault(temp, 0) + 1);
        }

        // For each prime factor p^e, compute the expected value contribution
        // The expected value of the product is the product of expected values for each prime power
        // For a prime p with exponent e, after k steps, the exponent becomes a random variable
        // Let's define f(e, k) = expected value of p^X where X is the exponent after k steps
        // Starting from exponent e, at each step, we pick a divisor uniformly at random.
        // The divisor of p^e is p^j for j=0,1,...,e, each with probability 1/(e+1).
        // So the transition: from exponent a, next exponent is j with prob 1/(a+1) for j=0..a.

